                allarme.OutAlarm += new BaseAlarm.ChangedEventHandler(ba_OutAlarm);
            }

            canctokenSource = new CancellationTokenSource();
            ct = canctokenSource.Token;
            _checkAlarms = Task.Factory.StartNew(() => run(), ct, TaskCreationOptions.DenyChildAttach, TaskScheduler.Default);
